// 참조표 공용 UI 요소
export function PanelCard({ children }) {
    return (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 sm:p-5">
            {children}
        </div>
    );
}

export function SectionHeader({ children }) {
    return (
        <h3 className="text-xs font-semibold tracking-widest uppercase text-rose-300/80 mb-3">
            {children}
        </h3>
    );
}

export function Bullet({ children }) {
    return (
        <li className="relative pl-4 text-[13px] leading-relaxed text-slate-200 before:absolute before:left-0 before:top-[0.55em] before:h-1 before:w-1 before:rounded-full before:bg-rose-400/60">
            {children}
        </li>
    );
}

const ACCENT = {
    rose:    "bg-rose-500/20 text-rose-200 ring-rose-400/30",
    amber:   "bg-amber-500/20 text-amber-200 ring-amber-400/30",
    red:     "bg-red-500/20 text-red-200 ring-red-400/30",
    emerald: "bg-emerald-500/20 text-emerald-200 ring-emerald-400/30",
    cyan:    "bg-cyan-500/20 text-cyan-200 ring-cyan-400/30",
};

export function PhaseStep({ n, title, accent = "rose", children }) {
    const chipCls = ACCENT[accent] || ACCENT.rose;
    return (
        <li className="rounded-xl bg-black/20 p-3 ring-1 ring-white/5">
            <div className="flex items-center gap-2 mb-2">
                <span className={`shrink-0 inline-flex items-center justify-center w-6 h-6 rounded-full text-[11px] font-bold ring-1 ${chipCls}`}>
                    {n}
                </span>
                <span className="text-sm font-semibold text-white">{title}</span>
            </div>
            <ul className="flex flex-col gap-1 pl-1">
                {children}
            </ul>
        </li>
    );
}

export function Formula({ children }) {
    return (
        <div className="rounded-lg bg-black/30 ring-1 ring-white/10 px-3 py-2 font-mono text-[13px] text-emerald-200 overflow-x-auto">
            {children}
        </div>
    );
}

export function KeyValue({ k, v, accent = "rose" }) {
    const col = accent === "rose" ? "text-rose-200" : accent === "amber" ? "text-amber-200" : "text-slate-300";
    return (
        <div className="flex items-start gap-2 text-[13px]">
            <span className={`shrink-0 font-semibold ${col}`}>{k}</span>
            <span className="text-slate-500">—</span>
            <span className="text-slate-200">{v}</span>
        </div>
    );
}
