import { useEffect, useState } from "react";

// 룰북 MD 전용의 경량 파서/렌더러.
// 지원: # ## ### 제목, * - 불릿, N. 번호 리스트, | 테이블 |, ---, ** 굵게, * 기울임, ` 코드, > 인용

// 모듈 수준 캐시 (탭 전환 시 재fetch 방지)
const CACHE = new Map();

async function fetchMd(path) {
    if (CACHE.has(path)) return CACHE.get(path);
    const res = await fetch(path, { cache: "no-store" });
    if (!res.ok) throw new Error(`Failed to load ${path}`);
    const text = await res.text();
    CACHE.set(path, text);
    return text;
}

// ---------- 인라인 치환 ----------
// `**` → bold, `*` → italic, ` → code
function renderInline(text) {
    if (!text) return null;
    // 각 토큰을 순차적으로 분할: `code` 우선, 그 다음 **bold**, 그 다음 *italic*
    const parts = [];
    let rest = text;
    let key = 0;
    while (rest.length > 0) {
        const codeM = rest.match(/`([^`]+)`/);
        const boldM = rest.match(/\*\*([^*]+)\*\*/);
        const italM = rest.match(/\*([^*\s][^*]*?)\*/);

        // 가장 빠른 매치 찾기
        const candidates = [
            codeM ? { m: codeM, kind: "code" } : null,
            boldM ? { m: boldM, kind: "bold" } : null,
            italM ? { m: italM, kind: "ital" } : null,
        ].filter(Boolean);

        if (candidates.length === 0) {
            parts.push(rest);
            break;
        }
        candidates.sort((a, b) => a.m.index - b.m.index);
        const first = candidates[0];
        const idx = first.m.index;
        if (idx > 0) parts.push(rest.slice(0, idx));
        const content = first.m[1];
        if (first.kind === "code") {
            parts.push(
                <code key={`k${key++}`} className="px-1 py-0.5 rounded bg-black/40 ring-1 ring-white/10 text-[0.85em] font-mono text-rose-100">
                    {content}
                </code>
            );
        } else if (first.kind === "bold") {
            parts.push(
                <strong key={`k${key++}`} className="font-semibold text-white">
                    {renderInline(content)}
                </strong>
            );
        } else {
            parts.push(
                <em key={`k${key++}`} className="italic text-rose-200/90">
                    {renderInline(content)}
                </em>
            );
        }
        rest = rest.slice(idx + first.m[0].length);
    }
    return parts;
}

// ---------- 블록 파싱 ----------
function parseBlocks(md) {
    const lines = md.split(/\r?\n/);
    const blocks = [];
    let i = 0;
    while (i < lines.length) {
        const line = lines[i];

        // 빈 줄
        if (!line.trim()) { i++; continue; }

        // 수평선
        if (/^---+$/.test(line.trim())) {
            blocks.push({ type: "hr" });
            i++;
            continue;
        }

        // 제목
        const hM = line.match(/^(#{1,6})\s+(.*)$/);
        if (hM) {
            blocks.push({ type: "heading", level: hM[1].length, text: hM[2] });
            i++;
            continue;
        }

        // 테이블 (`|...|` 라인이 연속)
        if (/^\s*\|.+\|\s*$/.test(line)) {
            const tableLines = [];
            while (i < lines.length && /^\s*\|.+\|\s*$/.test(lines[i])) {
                tableLines.push(lines[i].trim());
                i++;
            }
            if (tableLines.length >= 2) {
                const header = splitCells(tableLines[0]);
                const divider = tableLines[1];
                const rows = /^\s*\|?[\s:|-]+\|?\s*$/.test(divider)
                    ? tableLines.slice(2).map(splitCells)
                    : tableLines.slice(1).map(splitCells);
                blocks.push({ type: "table", header, rows });
                continue;
            }
            // 단일 라인은 그냥 문단 처리
            blocks.push({ type: "p", text: tableLines.join("\n") });
            continue;
        }

        // 리스트 (bullet / numbered)
        const bulletM = line.match(/^(\s*)([*-])\s+(.*)$/);
        const numM = line.match(/^(\s*)(\d+)\.\s+(.*)$/);
        if (bulletM || numM) {
            const ordered = !!numM;
            const items = [];
            while (i < lines.length) {
                const ln = lines[i];
                const bM = ln.match(/^(\s*)([*-])\s+(.*)$/);
                const nM = ln.match(/^(\s*)(\d+)\.\s+(.*)$/);
                if ((ordered && nM) || (!ordered && bM)) {
                    const indent = (ordered ? nM[1] : bM[1]).length;
                    const content = ordered ? nM[3] : bM[3];
                    if (indent >= 2 && items.length > 0) {
                        // 중첩: 직전 항목에 붙임
                        items[items.length - 1].sub = items[items.length - 1].sub || [];
                        items[items.length - 1].sub.push(content);
                    } else {
                        items.push({ text: content, sub: null });
                    }
                    i++;
                } else if (/^\s{2,}\S/.test(ln) && items.length > 0) {
                    // 들여쓴 이어지는 라인(서브 설명)
                    items[items.length - 1].sub = items[items.length - 1].sub || [];
                    items[items.length - 1].sub.push(ln.trim());
                    i++;
                } else {
                    break;
                }
            }
            blocks.push({ type: "list", ordered, items });
            continue;
        }

        // 인용
        if (/^>\s?/.test(line)) {
            const quoteLines = [];
            while (i < lines.length && /^>\s?/.test(lines[i])) {
                quoteLines.push(lines[i].replace(/^>\s?/, ""));
                i++;
            }
            blocks.push({ type: "quote", text: quoteLines.join("\n") });
            continue;
        }

        // 문단 (여러 줄 묶음)
        const paraLines = [];
        while (i < lines.length && lines[i].trim() && !/^(#{1,6}\s|\|.+\||---+$|>\s|\s*[-*]\s|\s*\d+\.\s)/.test(lines[i])) {
            paraLines.push(lines[i]);
            i++;
        }
        if (paraLines.length > 0) {
            blocks.push({ type: "p", text: paraLines.join(" ") });
        } else {
            i++;
        }
    }
    return blocks;
}

function splitCells(line) {
    let s = line.trim();
    if (s.startsWith("|")) s = s.slice(1);
    if (s.endsWith("|")) s = s.slice(0, -1);
    return s.split("|").map(c => c.trim());
}

// ---------- 블록 → React ----------
function renderBlocks(blocks) {
    return blocks.map((b, i) => {
        switch (b.type) {
            case "heading":
                return renderHeading(b, i);
            case "p":
                return (
                    <p key={i} className="text-[13px] leading-relaxed text-slate-200 mb-3">
                        {renderInline(b.text)}
                    </p>
                );
            case "list":
                return renderList(b, i);
            case "table":
                return renderTable(b, i);
            case "quote":
                return (
                    <blockquote key={i} className="my-3 rounded-lg border-l-4 border-rose-400/50 bg-rose-500/5 pl-3 pr-3 py-2 text-[13px] leading-relaxed text-rose-100/90">
                        {renderInline(b.text)}
                    </blockquote>
                );
            case "hr":
                return <hr key={i} className="my-5 border-white/10" />;
            default:
                return null;
        }
    });
}

function renderHeading(b, i) {
    const t = renderInline(b.text);
    if (b.level === 1) return <h1 key={i} className="text-xl sm:text-2xl font-bold text-white mt-4 mb-3">{t}</h1>;
    if (b.level === 2) return (
        <h2 key={i} className="text-lg font-bold text-rose-200 mt-5 mb-2 pb-1.5 border-b border-rose-400/20">
            {t}
        </h2>
    );
    if (b.level === 3) return <h3 key={i} className="text-sm font-semibold text-rose-100 mt-4 mb-2 tracking-wide">{t}</h3>;
    return <h4 key={i} className="text-sm font-semibold text-slate-200 mt-3 mb-1.5">{t}</h4>;
}

function renderList(b, i) {
    const Cls = b.ordered ? "ol" : "ul";
    const liCls = b.ordered
        ? "pl-1 py-0.5 text-[13px] text-slate-200 leading-relaxed list-decimal list-inside marker:text-rose-300/70"
        : "relative pl-4 py-0.5 text-[13px] text-slate-200 leading-relaxed before:absolute before:left-0 before:top-[0.7em] before:h-1 before:w-1 before:rounded-full before:bg-rose-400/60";
    const wrapCls = b.ordered
        ? "flex flex-col gap-1 mb-3"
        : "flex flex-col gap-1 mb-3";
    return (
        <Cls key={i} className={wrapCls}>
            {b.items.map((it, j) => (
                <li key={j} className={liCls}>
                    {renderInline(it.text)}
                    {it.sub && it.sub.length > 0 && (
                        <ul className="mt-1 ml-3 flex flex-col gap-0.5">
                            {it.sub.map((s, k) => (
                                <li key={k} className="relative pl-3 text-[12.5px] text-slate-300 leading-relaxed before:absolute before:left-0 before:top-[0.65em] before:h-0.5 before:w-1.5 before:bg-slate-500/60">
                                    {renderInline(s)}
                                </li>
                            ))}
                        </ul>
                    )}
                </li>
            ))}
        </Cls>
    );
}

function renderTable(b, i) {
    return (
        <div key={i} className="my-4 -mx-1 overflow-x-auto">
            <table className="w-full min-w-[500px] border-collapse text-sm">
                <thead>
                    <tr className="text-left text-rose-300/70 border-b border-white/10">
                        {b.header.map((h, j) => (
                            <th key={j} className="py-2 px-2.5 font-semibold tracking-wider text-[11px] uppercase">
                                {renderInline(h)}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {b.rows.map((row, k) => (
                        <tr key={k} className="border-b border-white/5 hover:bg-white/[0.02]">
                            {row.map((c, j) => (
                                <td key={j} className="py-2 px-2.5 align-top text-[12.5px] text-slate-200 leading-relaxed">
                                    {renderInline(c)}
                                </td>
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

// ---------- 컴포넌트 ----------
export default function MarkdownRef({ path }) {
    const [text, setText] = useState(CACHE.get(path) || "");
    const [error, setError] = useState(null);

    useEffect(() => {
        let cancelled = false;
        fetchMd(path)
            .then(t => { if (!cancelled) setText(t); })
            .catch(e => { if (!cancelled) setError(e.message); });
        return () => { cancelled = true; };
    }, [path]);

    if (error) {
        return (
            <div className="rounded-xl border border-rose-400/30 bg-rose-500/10 px-4 py-3 text-sm text-rose-200">
                문서를 불러오지 못했습니다: {error}
            </div>
        );
    }
    if (!text) {
        return (
            <div className="rounded-xl border border-white/10 bg-white/[0.02] px-4 py-8 text-center text-sm text-slate-500">
                문서 로딩 중...
            </div>
        );
    }

    const blocks = parseBlocks(text);
    return (
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4 sm:p-6">
            {renderBlocks(blocks)}
        </div>
    );
}
